SELECT sn.id AS note_id, sn.recordid AS invoice_id, t.tranid, TO_CHAR(sn.date, 'YYYY-MM-DD HH24:MI:SS') AS changed_at, sn.field, sn.oldvalue, sn.newvalue, BUILTIN.DF(sn.name) AS changed_by, sn.context FROM systemnote sn JOIN transaction t ON t.id = sn.recordid WHERE sn.recordtypeid = -30 AND sn.recordid IN (:doc_ids) AND sn.oldvalue IS NOT NULL ORDER BY sn.recordid, sn.date, sn.id
